// Helper — busca alíquota interestadual com fallback seguro
// Exportar esta função junto com a constante acima, ou colocar no TaxAnalyzer.jsx
export const getICMSRate = (origem, destino) => {
  if (!origem || !destino) return 12;
  const o = origem.toUpperCase().trim();
  const d = destino.toUpperCase().trim();
  return ICMS_INTERESTADUAL[o]?.[d] ?? 12;
};
